-- Olivia.az partner catalog (owner 2026-11-16): 51 curated products for the admin-only storefront.
-- Data only: public.products (already CDC + writer guarded) gets rows with store='olivia' and is_active=false,
-- so RLS ("Anyone can view active products") hides them from everyone except admins. Same rows as
-- src/data/olivia-products.json / oliviaImportRows(); Admin > Olivia mağazası removes or re-imports them in one click.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
DELETE FROM public.products WHERE store = 'olivia';
DO $$
BEGIN
  IF (SELECT count(*) FROM public.products WHERE store = 'olivia' AND is_active = false) <> 51
     OR EXISTS (SELECT 1 FROM public.products WHERE store = 'olivia' AND is_active) THEN
    RAISE EXCEPTION 'OLIVIA_CATALOG_COUNT_MISMATCH';
  END IF;
END $$;
COMMIT;
